CREATE OR REPLACE FUNCTION public.get_viewing_room_package(_token text,_package_id uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$
DECLARE board uuid; project uuid;
BEGIN
 IF _token IS NULL OR length(_token)>128 THEN RETURN NULL; END IF;
 SELECT p.moodboard_id,d.project_id INTO board,project FROM public.furniture_packages p JOIN public.residence_layouts r ON r.id=p.residence_layout_id JOIN public.developer_projects d ON d.id=r.developer_project_id JOIN public.client_boards b ON b.id=p.moodboard_id AND b.project_id=d.project_id WHERE p.id=_package_id AND d.access_token=_token;
 IF board IS NULL THEN RETURN NULL; END IF;
 RETURN jsonb_build_object('items',coalesce((SELECT jsonb_agg(jsonb_build_object('id',i.id,'product_name',t.product_name,'category',t.category,'subcategory',t.subcategory,'image_url',t.image_url,'dimensions',t.dimensions,'width_mm',t.width_mm,'depth_mm',t.depth_mm,'height_mm',t.height_mm,'glb_url',coalesce((SELECT c.glb_url_compressed FROM public.catalog_items c WHERE c.id=t.id),t.glb_url),'lead_time',t.lead_time,'materials',coalesce((SELECT jsonb_object_agg(m.slot,m.swatch) FROM (SELECT f.key AS slot,jsonb_build_object('id',fab.id,'name',fab.name,'category',fab.category,'brand_name','','image_url',fab.image_url,'material_type',fab.category,'color_family',null) AS swatch FROM public.project_studio_finishes s CROSS JOIN LATERAL jsonb_each_text(s.selection->'ids') f JOIN public.fabrics fab ON fab.id::text=f.value WHERE s.project_id=project AND s.item_key=i.id::text) m),'{}'::jsonb) || coalesce((SELECT jsonb_object_agg(m.slot,m.swatch) FROM (SELECT 'default-'||sw.fabric_id::text AS slot,jsonb_build_object('id',sw.fabric_id,'name',sw.name,'category',sw.category,'brand_name',coalesce(sw.supplier,''),'image_url',sw.image_url,'material_type',sw.category,'color_family',null) AS swatch FROM public.product_fabric_swatches_public sw WHERE sw.pick_id=t.id AND sw.is_active AND sw.image_url IS NOT NULL ORDER BY sw.sort_order NULLS LAST, sw.created_at LIMIT 4) m),'{}'::jsonb)) ORDER BY i.sort_order) FROM (SELECT * FROM public.client_board_items WHERE board_id=board ORDER BY sort_order LIMIT 50) i JOIN public.trade_products t ON t.id=i.product_id WHERE NOT EXISTS(SELECT 1 FROM public.project_studio_finishes s WHERE s.project_id=project AND s.item_key=i.id::text AND s.selection->>'excluded'='true')),'[]'::jsonb));
END; $$;
REVOKE ALL ON FUNCTION public.get_viewing_room_package(text,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_viewing_room_package(text,uuid) TO anon, authenticated;